import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Syarat dan Ketentuan layanan","description":"","frontmatter":{},"headers":[],"relativePath":"syarat-ketentuan.md","filePath":"syarat-ketentuan.md"}`),a={name:`syarat-ketentuan.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="syarat-dan-ketentuan-layanan" tabindex="-1">Syarat dan Ketentuan layanan <a class="header-anchor" href="#syarat-dan-ketentuan-layanan" aria-label="Permalink to “Syarat dan Ketentuan layanan”">​</a></h1><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to “1. Introduction”">​</a></h2><p>Welcome to <strong>Mikazuki AI</strong> (the &quot;Service&quot;), an AI character interaction platform operated by <strong>Rafiq8K Studio</strong> (&quot;we&quot;, &quot;us&quot;, &quot;our&quot;).</p><p>Mikazuki AI allows users to chat with AI-powered fictional characters, build simulated relationships, view character stories, and interact with various AI models through built-in or user-provided API keys.</p><p>By accessing or using the Service, you agree to be bound by these Terms of Service (&quot;Terms&quot;). If you do not agree to these Terms, please do not use the Service.</p><hr><h2 id="_2-acceptance-of-terms" tabindex="-1">2. Acceptance of Terms <a class="header-anchor" href="#_2-acceptance-of-terms" aria-label="Permalink to “2. Acceptance of Terms”">​</a></h2><p>By creating an account, accessing, or using Mikazuki AI in any way, you acknowledge that you have read, understood, and agree to be bound by:</p><ul><li>These Terms of Service</li><li>Our <a href="./kebijakan-privasi.html">Privacy Policy</a></li></ul><p>If you do not agree to any part of these Terms, you must discontinue use of the Service immediately.</p><hr><h2 id="_3-changes-to-terms" tabindex="-1">3. Changes to Terms <a class="header-anchor" href="#_3-changes-to-terms" aria-label="Permalink to “3. Changes to Terms”">​</a></h2><p>We reserve the right to modify or update these Terms at any time. Changes will be effective immediately upon posting. We will notify users of material changes through:</p><ul><li>In-app notifications</li><li>Email (if you have provided one)</li><li>A notice on our website</li></ul><p>Your continued use of the Service after any changes constitutes your acceptance of the new Terms. We encourage you to review these Terms periodically.</p><hr><h2 id="_4-eligibility" tabindex="-1">4. Eligibility <a class="header-anchor" href="#_4-eligibility" aria-label="Permalink to “4. Eligibility”">​</a></h2><p>By using the Service, you represent and warrant that:</p><ol><li>You are <strong>at least 16 years of age</strong>.</li><li>If you are between the ages of 16 and 18, you have obtained parental or legal guardian consent to use the Service.</li><li>You have the legal capacity to enter into a binding agreement.</li><li>You are not located in a country that is subject to a government embargo or that has been designated as supporting terrorism.</li><li>You are not a person barred from receiving services under applicable laws.</li></ol><p>The Service is not intended for children under the age of 16. We do not knowingly collect personal information from children under 16.</p><hr><h2 id="_5-user-accounts" tabindex="-1">5. User Accounts <a class="header-anchor" href="#_5-user-accounts" aria-label="Permalink to “5. User Accounts”">​</a></h2><h3 id="_5-1-registration" tabindex="-1">5.1 Registration <a class="header-anchor" href="#_5-1-registration" aria-label="Permalink to “5.1 Registration”">​</a></h3><p>You must create an account to access most features of the Service. You agree to provide accurate, current, and complete information during the registration process and to update such information as needed.</p><h3 id="_5-2-account-responsibility" tabindex="-1">5.2 Account Responsibility <a class="header-anchor" href="#_5-2-account-responsibility" aria-label="Permalink to “5.2 Account Responsibility”">​</a></h3><p>You are solely responsible for:</p><ul><li>Maintaining the confidentiality of your password and login credentials</li><li>All activities that occur under your account</li><li>Notifying us immediately of any unauthorized use of your account</li></ul><h3 id="_5-3-account-security" tabindex="-1">5.3 Account Security <a class="header-anchor" href="#_5-3-account-security" aria-label="Permalink to “5.3 Account Security”">​</a></h3><p>We take reasonable security measures to protect your account, including encrypted password storage, session management, and optional app lock. However, we cannot guarantee absolute security.</p><h3 id="_5-4-one-account-per-user" tabindex="-1">5.4 One Account Per User <a class="header-anchor" href="#_5-4-one-account-per-user" aria-label="Permalink to “5.4 One Account Per User”">​</a></h3><p>You may not create multiple accounts for abusive purposes. We reserve the right to merge or disable duplicate accounts.</p><h3 id="_5-5-email-verification" tabindex="-1">5.5 Email Verification <a class="header-anchor" href="#_5-5-email-verification" aria-label="Permalink to “5.5 Email Verification”">​</a></h3><p>You must verify your email address via a one-time password (OTP) sent to your registered email. Accounts with unverified emails may have restricted access.</p><hr><h2 id="_6-vip-donations" tabindex="-1">6. VIP / Donations <a class="header-anchor" href="#_6-vip-donations" aria-label="Permalink to “6. VIP / Donations”">​</a></h2><p>Mikazuki AI offers a <strong>VIP status</strong> that provides certain benefits such as priority AI model access and exclusive badges.</p><h3 id="_6-1-donation-platform" tabindex="-1">6.1 Donation Platform <a class="header-anchor" href="#_6-1-donation-platform" aria-label="Permalink to “6.1 Donation Platform”">​</a></h3><p>VIP status is granted through donations made via <strong>Trakteer</strong> (trakteer.id), a third-party donation platform. All donations are processed by Trakteer under their own terms and policies.</p><h3 id="_6-2-non-refundable" tabindex="-1">6.2 Non-Refundable <a class="header-anchor" href="#_6-2-non-refundable" aria-label="Permalink to “6.2 Non-Refundable”">​</a></h3><p>All donations are <strong>final and non-refundable</strong>. VIP status is a voluntary contribution to support the project, not a purchase of goods or services.</p><h3 id="_6-3-manual-granting" tabindex="-1">6.3 Manual Granting <a class="header-anchor" href="#_6-3-manual-granting" aria-label="Permalink to “6.3 Manual Granting”">​</a></h3><p>VIP status is granted manually by administrators. While we strive to process grants promptly, we do not guarantee instant activation.</p><h3 id="_6-4-no-subscription-obligation" tabindex="-1">6.4 No Subscription Obligation <a class="header-anchor" href="#_6-4-no-subscription-obligation" aria-label="Permalink to “6.4 No Subscription Obligation”">​</a></h3><p>VIP status has a defined duration and does not auto-renew. There is no obligation to continue donating to use the Service.</p><h3 id="_6-5-no-special-legal-rights" tabindex="-1">6.5 No Special Legal Rights <a class="header-anchor" href="#_6-5-no-special-legal-rights" aria-label="Permalink to “6.5 No Special Legal Rights”">​</a></h3><p>VIP status does not grant any ownership, equity, or special legal rights in the Service or its intellectual property.</p><hr><h2 id="_7-user-conduct" tabindex="-1">7. User Conduct <a class="header-anchor" href="#_7-user-conduct" aria-label="Permalink to “7. User Conduct”">​</a></h2><p>You agree not to engage in any of the following prohibited activities:</p><ol><li><strong>Harassment &amp; Abuse</strong>: Harassing, threatening, or abusing other users, administrators, or the platform itself.</li><li><strong>Illegal Content</strong>: Posting, sharing, or generating any content that violates applicable laws or regulations.</li><li><strong>NSFW Content with Minors</strong>: Engaging in sexually explicit or inappropriate conversations with characters marked as minors (under 16). This is a <strong>strict violation</strong> of our SFW Policy and will result in permanent suspension without warning.</li><li><strong>System Abuse</strong>: Exploiting bugs, manipulating the AI systems, or attempting to deceive the platform.</li><li><strong>Spam</strong>: Sending excessive automated messages or engaging in disruptive behavior.</li><li><strong>Impersonation</strong>: Impersonating another person, entity, or the platform&#39;s staff.</li><li><strong>Unauthorized Access</strong>: Attempting to access another user&#39;s account, admin features, or backend systems.</li><li><strong>Copyright Infringement</strong>: Violating the intellectual property rights of others.</li><li><strong>Commercial Use</strong>: Using the Service for commercial purposes without prior written consent.</li></ol><p>Violation of these rules may result in immediate account suspension or permanent ban without prior notice.</p><hr><h2 id="_8-user-content" tabindex="-1">8. User Content <a class="header-anchor" href="#_8-user-content" aria-label="Permalink to “8. User Content”">​</a></h2><h3 id="_8-1-what-you-submit" tabindex="-1">8.1 What You Submit <a class="header-anchor" href="#_8-1-what-you-submit" aria-label="Permalink to “8.1 What You Submit”">​</a></h3><p>&quot;User Content&quot; includes but is not limited to:</p><ul><li>Chat messages you send to AI characters</li><li>Your user persona/bio</li><li>Student (character) requests you submit</li><li>Backup data you create</li></ul><h3 id="_8-2-ownership" tabindex="-1">8.2 Ownership <a class="header-anchor" href="#_8-2-ownership" aria-label="Permalink to “8.2 Ownership”">​</a></h3><p>You retain all rights to the User Content you create. We do not claim ownership over your messages or persona.</p><h3 id="_8-3-license-to-us" tabindex="-1">8.3 License to Us <a class="header-anchor" href="#_8-3-license-to-us" aria-label="Permalink to “8.3 License to Us”">​</a></h3><p>By submitting User Content, you grant us a non-exclusive, worldwide, royalty-free, and limited license to:</p><ul><li>Transmit your content to provide the Service (your chat data stays on your device)</li><li>Use your content for AI inference (via our system AI or your own API keys)</li><li>Create backups for data restoration purposes</li></ul><p>This license is solely for the purpose of operating and improving the Service.</p><h3 id="_8-4-content-responsibility" tabindex="-1">8.4 Content Responsibility <a class="header-anchor" href="#_8-4-content-responsibility" aria-label="Permalink to “8.4 Content Responsibility”">​</a></h3><p>You are solely responsible for all User Content you submit. We reserve the right to review, modify, or remove content that violates these Terms.</p><hr><h2 id="_9-ai-chat-services" tabindex="-1">9. AI Chat Services <a class="header-anchor" href="#_9-ai-chat-services" aria-label="Permalink to “9. AI Chat Services”">​</a></h2><h3 id="_9-1-nature-of-ai-responses" tabindex="-1">9.1 Nature of AI Responses <a class="header-anchor" href="#_9-1-nature-of-ai-responses" aria-label="Permalink to “9.1 Nature of AI Responses”">​</a></h3><p>AI-generated responses are produced by large language models and may contain:</p><ul><li>Inaccurate or fictional information</li><li>Inappropriate or unexpected content</li><li>Repetitive or nonsensical text</li></ul><p><strong>AI responses do not reflect the views of Rafiq8K Studio.</strong> The Service uses multiple AI providers, and we cannot guarantee the accuracy, safety, or appropriateness of AI-generated content.</p><h3 id="_9-2-system-ai" tabindex="-1">9.2 System AI <a class="header-anchor" href="#_9-2-system-ai" aria-label="Permalink to “9.2 System AI”">​</a></h3><p>Our built-in System AI uses a chain of third-party AI providers to generate responses. The quality and availability of these providers may vary.</p><h3 id="_9-3-bring-your-own-key-byok" tabindex="-1">9.3 Bring Your Own Key (BYOK) <a class="header-anchor" href="#_9-3-bring-your-own-key-byok" aria-label="Permalink to “9.3 Bring Your Own Key (BYOK)”">​</a></h3><p>If you choose to use your own API keys for AI chat:</p><ul><li>You are responsible for all usage and costs incurred by your API keys.</li><li>Your API keys are stored locally on your device and are used solely for processing your chat requests. We do not store your API keys on our servers.</li><li>You must comply with the terms of service of your chosen AI provider.</li><li>We are not responsible for any data transmitted to third-party AI providers via your keys.</li></ul><h3 id="_9-4-bond-relationship-system" tabindex="-1">9.4 Bond / Relationship System <a class="header-anchor" href="#_9-4-bond-relationship-system" aria-label="Permalink to “9.4 Bond / Relationship System”">​</a></h3><p>The bond system (affection levels, relationship labels, milestone choices) is a <strong>simulated gameplay mechanic</strong> only. It does not represent a real relationship, contract, or legal bond between users and characters.</p><h3 id="_9-5-no-medical-or-professional-advice" tabindex="-1">9.5 No Medical or Professional Advice <a class="header-anchor" href="#_9-5-no-medical-or-professional-advice" aria-label="Permalink to “9.5 No Medical or Professional Advice”">​</a></h3><p>AI responses should not be taken as medical, legal, financial, or professional advice. If you need professional help, please consult a qualified professional.</p><hr><h2 id="_10-acceptable-use-policy-sfw-policy" tabindex="-1">10. Acceptable Use Policy (SFW Policy) <a class="header-anchor" href="#_10-acceptable-use-policy-sfw-policy" aria-label="Permalink to “10. Acceptable Use Policy (SFW Policy)”">​</a></h2><p>Mikazuki AI enforces a <strong>Safe for Work (SFW) Policy</strong> for interactions with characters marked as minors (under 16 years of age). This policy is documented in a separate document that forms part of these Terms.</p><p>Key points:</p><ul><li>Any sexually explicit, suggestive, or otherwise inappropriate content directed at minor characters is <strong>strictly prohibited</strong>.</li><li>Violations are detected through AI prompt analysis and may be reported to relevant authorities.</li><li><strong>Penalty</strong>: Permanent account suspension without warning. We reserve the right to report violations to law enforcement.</li></ul><p>By using the Service, you agree to comply with the SFW Policy.</p><hr><h2 id="_11-intellectual-property" tabindex="-1">11. Intellectual Property <a class="header-anchor" href="#_11-intellectual-property" aria-label="Permalink to “11. Intellectual Property”">​</a></h2><h3 id="_11-1-character-ips" tabindex="-1">11.1 Character IPs <a class="header-anchor" href="#_11-1-character-ips" aria-label="Permalink to “11.1 Character IPs”">​</a></h3><p>All fictional characters, names, designs, and related elements belong to their respective owners. Mikazuki AI is an independent, non-commercial project and is <strong>not affiliated with, endorsed by, or sponsored by</strong> any of the IP owners whose characters may appear in the Service.</p><h3 id="_11-2-application-code" tabindex="-1">11.2 Application Code <a class="header-anchor" href="#_11-2-application-code" aria-label="Permalink to “11.2 Application Code”">​</a></h3><p>The Mikazuki AI application code, design, logo, and brand assets are the exclusive property of <strong>Rafiq8K Studio</strong> unless otherwise noted. You may not copy, modify, distribute, sell, or reverse-engineer the application without prior written permission.</p><h3 id="_11-3-open-source-components" tabindex="-1">11.3 Open Source Components <a class="header-anchor" href="#_11-3-open-source-components" aria-label="Permalink to “11.3 Open Source Components”">​</a></h3><p>The Service may use open-source libraries and components. Such components are used in accordance with their respective licenses.</p><h3 id="_11-4-no-commercial-use" tabindex="-1">11.4 No Commercial Use <a class="header-anchor" href="#_11-4-no-commercial-use" aria-label="Permalink to “11.4 No Commercial Use”">​</a></h3><p>You may not use Mikazuki AI or its components for commercial purposes without explicit written permission from Rafiq8K Studio.</p><hr><h2 id="_12-third-party-services" tabindex="-1">12. Third-Party Services <a class="header-anchor" href="#_12-third-party-services" aria-label="Permalink to “12. Third-Party Services”">​</a></h2><p>Mikazuki AI integrates with several third-party services. Your use of these services is subject to their respective terms and policies:</p><table tabindex="0"><thead><tr><th>Service</th><th>Purpose</th><th>Link</th></tr></thead><tbody><tr><td><strong>Google Gemini API</strong></td><td>AI chat provider</td><td><a href="https://ai.google.dev/" target="_blank" rel="noreferrer">https://ai.google.dev/</a></td></tr><tr><td><strong>Anthropic Claude API</strong></td><td>AI chat provider</td><td><a href="https://www.anthropic.com/" target="_blank" rel="noreferrer">https://www.anthropic.com/</a></td></tr><tr><td><strong>Mistral AI API</strong></td><td>AI chat provider</td><td><a href="https://mistral.ai/" target="_blank" rel="noreferrer">https://mistral.ai/</a></td></tr><tr><td><strong>NVIDIA NIM API</strong></td><td>AI chat provider</td><td><a href="https://build.nvidia.com/" target="_blank" rel="noreferrer">https://build.nvidia.com/</a></td></tr><tr><td><strong>OpenRouter API</strong></td><td>AI chat provider</td><td><a href="https://openrouter.ai/" target="_blank" rel="noreferrer">https://openrouter.ai/</a></td></tr><tr><td><strong>DeepSeek API</strong></td><td>AI chat provider</td><td><a href="https://deepseek.com/" target="_blank" rel="noreferrer">https://deepseek.com/</a></td></tr><tr><td><strong>Trakteer</strong></td><td>Donation platform</td><td><a href="https://trakteer.id" target="_blank" rel="noreferrer">https://trakteer.id</a></td></tr><tr><td><strong>Cloudflare</strong></td><td>CDN, DNS, Workers</td><td><a href="https://www.cloudflare.com/" target="_blank" rel="noreferrer">https://www.cloudflare.com/</a></td></tr><tr><td><strong>Discord</strong></td><td>Community &amp; support</td><td><a href="https://discord.com/" target="_blank" rel="noreferrer">https://discord.com/</a></td></tr><tr><td><strong>Brevo</strong></td><td>Email delivery</td><td><a href="https://www.brevo.com/" target="_blank" rel="noreferrer">https://www.brevo.com/</a></td></tr></tbody></table><p>We are not responsible for the content, policies, or practices of third-party services.</p><hr><h2 id="_13-privacy" tabindex="-1">13. Privacy <a class="header-anchor" href="#_13-privacy" aria-label="Permalink to “13. Privacy”">​</a></h2><p>Your privacy is important to us. Please refer to our separate <strong><a href="./kebijakan-privasi.html">Privacy Policy</a></strong> for detailed information about:</p><ul><li>What personal data we collect (email, name, device info)</li><li>How we use and store your data</li><li>Data retention periods</li><li>Your rights regarding your data</li><li>Third-party data sharing</li></ul><p>The Privacy Policy forms part of these Terms.</p><hr><h2 id="_14-disclaimer-limitation-of-liability" tabindex="-1">14. Disclaimer &amp; Limitation of Liability <a class="header-anchor" href="#_14-disclaimer-limitation-of-liability" aria-label="Permalink to “14. Disclaimer &amp; Limitation of Liability”">​</a></h2><h3 id="_14-1-service-as-is" tabindex="-1">14.1 Service &quot;As Is&quot; <a class="header-anchor" href="#_14-1-service-as-is" aria-label="Permalink to “14.1 Service &quot;As Is&quot;”">​</a></h3><p>MIKAZUKI AI IS PROVIDED &quot;AS IS&quot; AND &quot;AS AVAILABLE&quot; WITHOUT ANY WARRANTIES OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, OR NON-INFRINGEMENT.</p><h3 id="_14-2-no-guarantee" tabindex="-1">14.2 No Guarantee <a class="header-anchor" href="#_14-2-no-guarantee" aria-label="Permalink to “14.2 No Guarantee”">​</a></h3><p>We do not guarantee that:</p><ul><li>The Service will be uninterrupted, timely, secure, or error-free</li><li>AI responses will be accurate, reliable, or appropriate</li><li>Any data you store will not be lost or corrupted</li></ul><h3 id="_14-3-limitation-of-liability" tabindex="-1">14.3 Limitation of Liability <a class="header-anchor" href="#_14-3-limitation-of-liability" aria-label="Permalink to “14.3 Limitation of Liability”">​</a></h3><p>TO THE MAXIMUM EXTENT PERMITTED BY APPLICABLE LAW, RAFIQ8K STUDIO SHALL NOT BE LIABLE FOR ANY INDIRECT, INCIDENTAL, SPECIAL, CONSEQUENTIAL, OR PUNITIVE DAMAGES ARISING OUT OF OR RELATED TO YOUR USE OF THE SERVICE.</p><h3 id="_14-4-non-commercial-project" tabindex="-1">14.4 Non-Commercial Project <a class="header-anchor" href="#_14-4-non-commercial-project" aria-label="Permalink to “14.4 Non-Commercial Project”">​</a></h3><p>Mikazuki AI is a <strong>non-commercial, independent project</strong> operated on a best-effort basis. We provide no service-level guarantees.</p><hr><h2 id="_15-termination" tabindex="-1">15. Termination <a class="header-anchor" href="#_15-termination" aria-label="Permalink to “15. Termination”">​</a></h2><h3 id="_15-1-termination-by-us" tabindex="-1">15.1 Termination by Us <a class="header-anchor" href="#_15-1-termination-by-us" aria-label="Permalink to “15.1 Termination by Us”">​</a></h3><p>We reserve the right to suspend or terminate your account at any time, without prior notice, for:</p><ul><li>Violation of these Terms (including the SFW Policy)</li><li>Conduct that we believe is harmful to the Service or other users</li><li>Extended inactivity</li><li>At our sole discretion</li></ul><h3 id="_15-2-termination-by-you" tabindex="-1">15.2 Termination by You <a class="header-anchor" href="#_15-2-termination-by-you" aria-label="Permalink to “15.2 Termination by You”">​</a></h3><p>You may stop using the Service at any time.</p><h3 id="_15-3-effect-of-termination" tabindex="-1">15.3 Effect of Termination <a class="header-anchor" href="#_15-3-effect-of-termination" aria-label="Permalink to “15.3 Effect of Termination”">​</a></h3><p>Upon termination:</p><ul><li>Your access to the Service will be revoked</li><li>We may delete your data in accordance with our Privacy Policy</li><li>These Terms will survive termination as necessary</li></ul><h3 id="_15-4-appeal" tabindex="-1">15.4 Appeal <a class="header-anchor" href="#_15-4-appeal" aria-label="Permalink to “15.4 Appeal”">​</a></h3><p>If your account has been suspended or banned and you believe it was in error, you may appeal by contacting <strong><a href="mailto:support@r8kstudio.net" target="_blank" rel="noreferrer">support@r8kstudio.net</a></strong>. We will review appeals on a case-by-case basis.</p><hr><h2 id="_16-governing-law-dispute-resolution" tabindex="-1">16. Governing Law &amp; Dispute Resolution <a class="header-anchor" href="#_16-governing-law-dispute-resolution" aria-label="Permalink to “16. Governing Law &amp; Dispute Resolution”">​</a></h2><p>These Terms shall be governed by and construed in accordance with the <strong>laws of the Republic of Indonesia</strong>, without regard to its conflict of law provisions.</p><p>Any disputes arising out of or relating to these Terms or the Service shall first be attempted to be resolved through informal negotiation. If the dispute cannot be resolved within 30 days, it shall be resolved in the <strong>courts of Indonesia</strong>.</p><p>You agree to submit to the personal jurisdiction of the courts located in Indonesia for the resolution of any disputes.</p><hr><h2 id="_17-contact-information" tabindex="-1">17. Contact Information <a class="header-anchor" href="#_17-contact-information" aria-label="Permalink to “17. Contact Information”">​</a></h2><p>If you have any questions, concerns, or requests regarding these Terms, please contact us:</p><ul><li><strong>Email:</strong> <a href="mailto:support@r8kstudio.net" target="_blank" rel="noreferrer">support@r8kstudio.net</a></li><li><strong>Developer:</strong> Rafiq8K Studio</li><li><strong>Discord:</strong> <a href="https://s.my-bini.my.id/discord" target="_blank" rel="noreferrer">Join our community</a></li><li><strong>Donation:</strong> <a href="https://trakteer.id/r8kstudio" target="_blank" rel="noreferrer">https://trakteer.id/r8kstudio</a></li></ul><hr><p><em>These Terms of Service were last updated on July 25, 2026.</em></p>`,139)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};